        marca: this.marca,
        modelo: this.modelo,
        transmicion: this.transmicion,
        combustible: this.combustible,
        traccion: this.traccion,
        color: this.color,
        anio: this.anio,
        chapa: this.chapa,
        chasis: this.chasis,
        observacion: this.observacion
      }, configuracion).then(function (response) {
        me.ocultarNuevo();
