      var me = this;
      var header = {
        Token: this.$store.state.token
      };
      var configuracion = {
        headers: header
      };
      axios.put("venta/activate", {
        _id: this.adId
      }, configuracion).then(function (response) {
        me.adModal = 0;
        me.adAccion = 0;
        me.adNombre = "";
        me.adId = "";
        me.listar();
      }).catch(function (error) {
        console.log(error);
      });
    },
