      };
      var configuracion = {
        headers: header
      };
      axios.put("venta/deactivate", {
        _id: this.adId
      }, configuracion).then(function (response) {
        me.adModal = 0;
        me.adAccion = 0;
        me.adNombre = "";
        me.adId = "";
        me.listar();
      }).catch(function (error) {
        console.log(error);
      });
    },
    close: function close() {
      this.dialog = false;
      this.dialogoCliente = false;
      this.limpiar();
    },
    guardarCliente: function guardarCliente() {
      var me = this;
      var header = {
        "auth-token": this.$store.state.token
      };
      var configuracion = {
        headers: header
      }; // if (this.validar()) {
      //   return;
      // }

      if (this.editedIndex > -1) {
        //Código para editar
        console.log(this.Ciudad);
        axios.put("clientes/", {
          CodigoCliente: this.CodigoCliente,
          CodigoCiudad: this.CodigoCiudad,
          RazonSocial: this.RazonSocial,
          Cedula: this.Cedula,
          Ruc: this.Ruc,
          Ciudad: this.Ciudad,
          Direccion: this.Direccion,
          Telefono: this.Telefono,
          Email: this.Email
        }, configuracion).then(function (response) {
          me.limpiar();
          me.close();
          me.listar();
          me.dialogoConfirmacion = true;
        }).catch(function (error) {
          console.log(error);
        });
      } else {
        //Código para guardar
        axios.post("clientes/", {
          CodigoCiudad: this.CodigoCiudad,
          RazonSocial: this.RazonSocial,
          Cedula: this.Cedula,
          Ruc: this.Ruc,
          Ciudad: this.Ciudad,
          Direccion: this.Direccion,
          Telefono: this.Telefono,
          Email: this.Email
        }, configuracion).then(function (response) {
          me.limpiar();
          me.close();
          me.listar();
          me.dialogoConfirmacion = true;
        }).catch(function (error) {
          console.log(error);
        });
      }
    }
  }
};
